function _b1shuf(arr){return arr.slice().sort(()=>Math.random()-.5);}
function _b1wrs(ans,min,max){return _b1shuf([ans-2,ans-1,ans+1,ans+2,ans+3].filter(v=>v>=min&&v<=max&&v!==ans)).slice(0,3).map(String);}
