  return{q:_b1q(svg,'¿Cuántos centímetros mide la barra azul?'),a:cm+' cm',opts:_b1s([cm+' cm',..._b1w(cm,1,15).map(v=>v+' cm')]),mc:true,ste:'La barra mide '+cm+' cm.'};
