function _s3rnd(a,b){return Math.floor(Math.random()*(b-a+1))+a;}
function _s3wrs(ans){
  return [ans-1,ans+1,ans-10,ans+10,ans+100,ans-100].filter(function(v){return v!==ans&&v>0;}).sort(function(){return Math.random()-0.5;}).slice(0,3);
}
