// ── UNIDAD: Polígonos — Ángulos, Regulares y Diagonales ─────────────────────
function _a6polyPath(n,cx,cy,r,rot0){
  let d='';
  for(let i=0;i<n;i++){const a=2*Math.PI*i/n+rot0;d+=`${i?'L':'M'}${(cx+r*Math.cos(a)).toFixed(1)} ${(cy+r*Math.sin(a)).toFixed(1)}`;}
  return d+'Z';
}
