    return {q:'Si x−y='+d+' y xy='+p+', halla x²+y²',a:''+ans,opts:sh([''+ans,''+(d*d),''+(d*d+p),''+(d*d+4*p)]),mc:true,ste:'(x−y)²='+d*d+'=x²−'+2*p+'+y². x²+y²='+d*d+'+'+2*p+'='+ans+'.'};
