  const answers = h.answers || [];
  const reEvalAnswers = answers.map(a => ({ ...a, correct: _prepReEvalAnswer(a) }));
  const reCorrect = reEvalAnswers.filter(a=>a.correct).length;
  const reTotal   = reEvalAnswers.length || h.total || 1;
