function _genDsComb21(){const sqs=[4,9,16,25,36,49,64,81,100],sq=sqs[_dsRi(0,sqs.length-1)],r=Math.sqrt(sq),c=_dsRi(2,9);return{algo:'comb',tokens:[c,'×',1,'√',sq],a:String(c*r),q:`${c} × √${sq}`};}
